    {
      "category": "bridged_nets",
      "components": ["U8", "U5", "D4"],
      "pins": ["U8.13", "U5.1", "U5.2", "D4.1"],
      "nets": ["NET0004"],
      "observed": "On the Microcontroller sheet, NET0004 connects ESP32 GPIO1 to the heater switch inputs U5.IN and U5.DIAG_EN, and also to D4.DIN, the WS2812B data input.",
      "expected": "The WS2812B data input should use a separate MCU GPIO from the heater-control signal so the LED can receive its own serial data without sharing the heater control net.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "GPIO1/ADC1_CH1 ... NET0004; U5 IN ... NET0004; D4 DIN ... NET0004 (Microcontroller sheet, page 2)",
        },
        {
          "source": "spec",
          "quote": "Drives a single heater output net through a smart high-side switch ... switched from the ESP32's GPIO1"
        },
        {
          "source": "spec",
          "quote": "a single onboard WS2812B status LED (D1)"
        }
      ],
      "impact": "The WS2812B cannot be independently controlled as a status LED while its data input shares the heater on/off signal. Heater switching may produce invalid LED data, and the LED input also loads the heater-control net.",
      "confidence": 0.98
    }
  ],
  "summary": "The schematic ties the WS2812B data input to the same net as ESP32 GPIO1 and the heater-switch inputs. This prevents independent status-LED control and is a clear deviation from the intended separate heater-control and status functions."
}

